function segmentsIntersect(A,B,C,D){const o1=orientation(A,B,C),o2=orientation(A,B,D),o3=orientation(C,D,A),o4=orientation(C,D,B);if(o1!==o2&&o3!==o4)return true;if(o1===0&&onSegment(A,C,B))return true;if(o2===0&&onSegment(A,D,B))return true;if(o3===0&&onSegment(C,A,D))return true;if(o4===0&&onSegment(C,B,D))return true;return false;}
function convexHull(points){
  if(points.length<=2)return points;
  let anchor=points[0];for(const p of points)if(p[1]<anchor[1]||(p[1]===anchor[1]&&p[0]<anchor[0]))anchor=p;
  const others=points.filter(p=>p!==anchor);
  others.sort((A,B)=>{const c=cross(anchor,A,B);if(c!==0)return c>0?-1:1;const dA=(A[0]-anchor[0])**2+(A[1]-anchor[1])**2,dB=(B[0]-anchor[0])**2+(B[1]-anchor[1])**2;return dA-dB;});
  const hull=[anchor];for(const p of others){while(hull.length>=2){const top=hull[hull.length-1],prev=hull[hull.length-2];if(cross(prev,top,p)<=0)hull.pop();else break;}hull.push(p);}
  return hull;
}
