function rectangleArea(rectangles){
  const MOD=1e9+7;const ySet=new Set();
  for(const[x1,y1,x2,y2]of rectangles){ySet.add(y1);ySet.add(y2);}
  const yCoords=[...ySet].sort((a,b)=>a-b);const yMap=new Map(yCoords.map((y,i)=>[y,i]));const m=yCoords.length;
  const events=[];for(const[x1,y1,x2,y2]of rectangles){events.push([x1,1,y1,y2]);events.push([x2,-1,y1,y2]);}
  events.sort((a,b)=>a[0]-b[0]);
  const count=new Array(m).fill(0);let prevX=0,result=0;
  for(const[x,type,y1,y2]of events){let coveredY=0;for(let i=0;i<m-1;i++)if(count[i]>0)coveredY+=yCoords[i+1]-yCoords[i];result=(result+coveredY*(x-prevX))%MOD;prevX=x;for(let i=yMap.get(y1);i<yMap.get(y2);i++)count[i]+=type;}
  return result;
}
const rectangleAreaImpl=rectangleArea;

