const MODULE6=[{id:149,algorithm:'Slope fraction',nc150:true,productTrack:true},{id:587,algorithm:'Convex Hull',nc150:true,productTrack:false},{id:850,algorithm:'Line sweep + seg tree',nc150:true,productTrack:false}];

function selectGeometryAlgo(signal){
  if(signal.includes('collinear')||signal.includes('orientation')||signal.includes('intersection'))return'Cross Product';
  if(signal.includes('convex')||signal.includes('hull'))return'Graham Scan';
  if(signal.includes('union')||signal.includes('segment intersect')||signal.includes('sweep'))return'Line Sweep';
  if(signal.includes('closest')||signal.includes('minimum distance'))return'Closest Pair D&C';
  if(signal.includes('overlap')||signal.includes('rectangle'))return'Direct Arithmetic';
  return'Cross Product';
}

function module6Summary(){
  return{total:MODULE6.length,nc150:MODULE6.filter(p=>p.nc150).length,productTrack:MODULE6.filter(p=>p.productTrack).length};
}
